  "crm": {"smithable.content.yml":"# Visible text. Only what differs from the texts Smithable derives from names.\nsmithableContent: 0.1\n\nmodels:\n  Customer:\n    fields:\n      segment:\n        values: { smb: Small business }\n      creditLimit:\n        help: Orders are held when the outstanding balance goes above this amount.\n  Order:\n    fields:\n      placedAt: { label: Placed on }\n","smithable.yml":"smithable: 0.1\n\napp:\n  name: Acme CRM\n  description: Lightweight CRM for a small B2B sales team.\n  currency: EUR\n  timezone: Europe/Mariehamn\n\nmodels:\n  Customer:\n    description: A company we have a commercial relationship with.\n    fields:\n      name: string!\n      email: email unique\n      phone: phone\n      segment: smb | enterprise | government      # first value is the default\n      creditLimit:\n        type: money\n        min: 0\n        description: Maximum outstanding balance before new orders are held.\n      notes: text\n      orders: Order[]                # every order that refers to this customer\n\n  Order:\n    fields:\n      number: string! unique\n      customer: Customer!\n      status: draft | placed | shipped | cancelled\n      total: money!\n      shippingMethod: standard | express\n      shippingCost:\n        type: money\n        formula: IF(AND(shippingMethod = \"standard\", total > 100), 0, IF(shippingMethod = \"express\", 15, 5))\n        description: Standard shipping is free above 100 EUR, otherwise 5 EUR. Express always costs 15 EUR.\n        examples:\n          - input: { total: 150, shippingMethod: standard }\n            expected: 0\n          - input: { total: 80, shippingMethod: standard }\n            expected: 5\n          - input: { total: 150, shippingMethod: express }\n            expected: 15\n      placedAt: datetime\n\npages:\n  customers:\n    intent: Find a customer quickly and keep their details current.\n    crud: Customer\n  orders:\n    crud: Order\n\nnavigation: [customers, orders]\n"},
